app-pill[disableTooltip] .pill, app-fancy-pill[disableTooltip] .pill { padding-right: 10px; }
app-status-pill[disableTooltip] .pill { border-style: dashed; }
app-card[disableTooltip] h3 { text-decoration: none; }

