const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, 'src');
const targetTags = ['app-pill', 'app-fancy-pill', 'app-status-pill'];

function walk(dir, files) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full, files);
        else if (entry.name.endsWith('.ts') || entry.name.endsWith('.html')) files.push(full);
    }
    return files;
}

const files = walk(root, []);
let totalChanges = 0;
const changedFiles = [];

for (const file of files) {
    let text = fs.readFileSync(file, 'utf8');
    let changesInFile = 0;

    for (const tag of targetTags) {
        // Match "<tag" followed by attributes up to the first unquoted '>'.
        // Attribute values may contain '>' when quoted (e.g. [disableTooltip]="count > 5").
        const tagRe = new RegExp(`<${tag}(?:[^>"']|"[^"]*"|'[^']*')*>`, 'g');
        text = text.replace(tagRe, (match) => {
            const replaced = match
                .replace(/\[disableTooltip\]/g, '[hideHint]')
                .replace(/\bdisableTooltip\b/g, 'hideHint');
            if (replaced !== match) changesInFile += 1;
            return replaced;
        });
    }

    if (changesInFile > 0) {
        fs.writeFileSync(file, text, 'utf8');
        totalChanges += changesInFile;
        changedFiles.push([file, changesInFile]);
    }
}

console.log('Files changed:', changedFiles.length);
console.log('Total tag replacements:', totalChanges);
for (const [f, c] of changedFiles) console.log(c, f);

