const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, 'src');

function walk(dir, files) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full, files);
        else if (entry.name.endsWith('.ts') || entry.name.endsWith('.html')) files.push(full);
    }
    return files;
}

const files = walk(root, []);
// Receivers confirmed (via tsc errors) to be PillComponent/FancyPillComponent instances.
const receivers = ['fancy\\.', 'fancyRef\\.', 'pill\\.', 'this\\.fancy\\(\\)\\??\\.', 'this\\.firstPill\\(\\)\\??\\.'];
const re = new RegExp(`(${receivers.join('|')})disableTooltip\\(\\)`, 'g');

let total = 0;
for (const file of files) {
    let text = fs.readFileSync(file, 'utf8');
    const newText = text.replace(re, (m, recv) => recv + 'hideHint()');
    if (newText !== text) {
        const count = (text.match(re) || []).length;
        total += count;
        fs.writeFileSync(file, newText, 'utf8');
        console.log(count, file);
    }
}
console.log('Total replacements:', total);

